con.execute("CREATE TABLE ck AS SELECT * FROM '"+CK+"'")
con.execute("""CREATE TABLE loc_m AS SELECT location_id, count(*) n_chk, sum(gross_ext) gross, sum(void_amt)/sum(gross_ext) void_rate, sum(cdisc+idisc)/sum(gross_ext) disc_rate, avg((gross_ext>0 AND sold-cdisc<=0.005)::INT) comp_chk_rate FROM ck GROUP BY 1""")
con.execute("""CREATE TABLE loc_c AS SELECT location_id, sum(amount) FILTER (WHERE pay_cat_name='CASH')/sum(amount) cash_share, count(*) FILTER (WHERE amount<0) neg_pay FROM payments GROUP BY 1""")
con.execute("""CREATE TABLE loc_w AS SELECT location_id, count(*) n_walk FROM (SELECT location_id, discount_name FROM item_discounts UNION ALL SELECT location_id, discount_name FROM check_discounts) WHERE discount_name='WALKOUT' GROUP BY 1""")
show("store spread (127 stores)", """SELECT round(min(void_rate)*100,2) v_min, round(median(void_rate)*100,2) v_med, round(max(void_rate)*100,2) v_max, round(min(disc_rate)*100,2) d_min, round(median(disc_rate)*100,2) d_med, round(max(disc_rate)*100,2) d_max,
 round(min(cash_share)*100,1) c_min, round(median(cash_share)*100,1) c_med, round(max(cash_share)*100,1) c_max, round(median(comp_chk_rate)*100,2) comp_med, round(max(comp_chk_rate)*100,2) comp_max FROM loc_m JOIN loc_c USING (location_id)""")
show("top stores by void rate", "SELECT location_id, l.Name AS name, n_chk, round(void_rate*100,2) void_pct, round(disc_rate*100,2) disc_pct, round(cash_share*100,1) cash_pct, coalesce(n_walk,0) walkouts, round(comp_chk_rate*100,2) comp_pct FROM loc_m JOIN loc_c USING (location_id) LEFT JOIN loc_w USING (location_id) JOIN loc l ON l.Id=location_id ORDER BY void_rate DESC LIMIT 6")
show("walkouts by store: top & median", "SELECT approx_quantile(coalesce(n_walk,0),[0.5]) med, max(n_walk) mx, count(*) FILTER (WHERE n_walk IS NULL) zero_stores FROM loc_m LEFT JOIN loc_w USING (location_id)")
show("store 80 daily around gap", "SELECT dt, count(*) n FROM ck WHERE location_id=80 AND dt BETWEEN '2026-08-08' AND '2026-08-20' GROUP BY 1 ORDER BY 1", 15)
show("tips: cash gratuity", "SELECT round(avg((-gratuity)/nullif(amount+gratuity,0)) FILTER (WHERE is_credit_card AND amount+gratuity>0)*100,1) card_tip_pct FROM payments")
show("outliers: checks", "SELECT approx_quantile(sold,[0.5,0.99,0.999]) sold_q, max(sold) mx_sold, approx_quantile(n_items,[0.5,0.99]) items_q, max(n_items) mx_items, max(traffic_count) mx_guests, count(*) FILTER (WHERE sold>1000) gt1k FROM ck")
